mapper.select:
SELECT 
FROM loyalty.point_ledger
WHERE tenant_id = #{tenantId} AND program_id = #{programId} AND id = #{id}

SELECT 
FROM loyalty.point_ledger
WHERE tenant_id = #{tenantId} AND program_id = #{programId}
  AND account_id = #{accountId} AND point_type_id = #{pointTypeId}
  AND transaction_type IN ('EARN','ADJUST','RECALCULATE') AND amount > 0

SELECT 
FROM loyalty.point_ledger
WHERE tenant_id = #{tenantId} AND program_id = #{programId}
  AND source_type = #{sourceType} AND source_id = #{sourceId}

SELECT 
FROM loyalty.point_ledger
WHERE tenant_id = #{tenantId} AND program_id = #{programId}
  AND account_id = #{accountId} AND point_type_id = #{pointTypeId}
  AND effective_at >= #{from}

    AND (created_at < #{cursorTime}
         OR (created_at = #{cursorTime} AND id < #{cursorId}))

ORDER BY created_at DESC, id DESC
LIMIT #{limit}
